	// trigger re-resolve. Also record this as a resolver error so the eventual
	// picker reports why the balancer is in TransientFailure.
	// An empty address list is invalid. Return an error so ClientConn will
	// trigger re-resolution with exponential backoff.
	if len(s.ResolverState.Addresses) == 0 {
		b.ResolverError(errors.New("produced zero addresses"))
